import {readCries,validateCryEdits} from './cry-editor.js';
import {decodeWave,readWAV,writeWAV,transformSample} from './pcm-sample.js';
export function cryWorkshop(api){
 const $=s=>document.querySelector(s),esc=api.esc;let audio,player,serial=0;
 function stop(){serial++;try{player?.stop();}catch{}player=null;}
 async function play(sample,reversed=false){stop();const request=serial;audio??=new(globalThis.AudioContext||globalThis.webkitAudioContext)();await audio.resume();if(request!==serial)return;const buffer=audio.createBuffer(1,sample.pcm.length,sample.rate),pcm=buffer.getChannelData(0);for(let i=0;i<pcm.length;i++)pcm[i]=(sample.pcm[reversed?pcm.length-1-i:i]<<24>>24)/128*.7;player=audio.createBufferSource();player.buffer=buffer;player.connect(audio.destination);player.start();}
 function open(){try{
  stop();const session=api.session();if(!session)throw Error('Open the original ROM first.');const project=api.project(),hash=session.id,reader=session.reader,native=readCries(reader,hash),draft=structuredClone(project.cryEdits?.[hash]||{});let id=native.rows[0].id,sample,history=[],dirty=false;
  api.modal('Pokémon cries',`<p>Replace the samples used by native cries. Each entry supplies normal and reverse cry modes; battle pitch and envelope effects remain controlled by the game.</p><label>Find a cry<input id="crySearch" type="search" placeholder="Pokémon or cry number"></label><label>Native cry<select id="crySelect"></select></label><p id="cryStatus" class="studio-status"></p><p id="cryError" role="alert"></p><canvas id="cryWave" width="640" height="120" aria-label="Cry waveform" style="display:block;width:100%;height:120px"></canvas><div class="studio-actions"><button id="cryPlay" type="button">▶ Preview</button><button id="cryReversePreview" type="button">▶ Reverse mode</button><button id="cryStop" type="button">Stop</button><button id="cryImport" type="button">Import WAV</button><button id="cryExport" type="button">Export WAV</button></div><input id="cryFile" type="file" accept=".wav,audio/wav" hidden><div class="form-grid"><label>Trim start (seconds)<input id="cryStart" type="number" min="0" step="0.001" value="0"></label><label>Trim end (seconds)<input id="cryEnd" type="number" min="0.001" step="0.001"></label><label>Gain (%)<input id="cryGain" type="number" min="0" max="200" value="100"></label><label>Pitch (semitones)<input id="cryPitch" type="number" min="-12" max="12" value="0"></label></div><label><input id="cryNormalize" type="checkbox"> Normalize volume</label><label><input id="cryReverse" type="checkbox"> Reverse sample</label><div class="studio-actions"><button id="cryApply" type="button">Apply audio edits</button><button id="cryUndo" type="button">Undo audio edit</button><button id="cryReset" type="button">Restore source cry</button></div><p class="hint-line">Import mono/stereo 8/16-bit PCM WAV, up to three seconds. Imports become mono 10,512 Hz, 8-bit samples. Use Apply audio edits before saving. Replacements are stored with this project and written when you export the matching source ROM. Preview plays the sample without the game’s battle effects. Native modes may cut long samples short. Cry numbers and names follow the opened ROM’s native tables.</p>`,()=>{
   stop();if(!dirty)return;if(api.project()!==project||api.session()?.reader!==reader)throw Error('Reopen this cry editor for the current project and ROM.');const edits={...project.cryEdits,[hash]:draft};validateCryEdits(edits);api.change(()=>{project.cryEdits=edits;});api.toast('Cry edits saved. Export the edited ROM to use them.');
  },'Save cry edits');
  const canvas=$('#cryWave'),select=$('#crySelect');
  function status(){const n=Object.keys(draft).length;$('#cryStatus').textContent=`${native.rows.find(row=>row.id===id).name} · cry ${id} · ${(sample.pcm.length/sample.rate).toFixed(3)} s · ${sample.rate.toFixed(0)} Hz · ${draft[id]?'Edited':'Source'} · ${n} replacements`;$('#cryUndo').disabled=!history.length;}
  function draw(){const ctx=canvas.getContext('2d');ctx.fillStyle='#1c1930';ctx.fillRect(0,0,640,120);ctx.strokeStyle='#acb2d5';ctx.beginPath();ctx.moveTo(0,60);ctx.lineTo(640,60);ctx.stroke();ctx.strokeStyle='#85e2b3';ctx.beginPath();for(let x=0;x<640;x++){const start=Math.floor(x*sample.pcm.length/640),end=Math.max(start+1,Math.ceil((x+1)*sample.pcm.length/640));let lo=0,hi=0;for(let i=start;i<end&&i<sample.pcm.length;i++){const value=sample.pcm[i]<<24>>24;lo=Math.min(lo,value);hi=Math.max(hi,value);}ctx.moveTo(x,60-hi/128*55);ctx.lineTo(x,60-lo/128*55);}ctx.stroke();status();}
  function controls(){$('#cryStart').value=0;$('#cryEnd').value=sample.pcm.length/sample.rate;$('#cryGain').value=100;$('#cryPitch').value=0;$('#cryNormalize').checked=false;$('#cryReverse').checked=false;draw();}
  function load(){stop();const row=native.rows.find(row=>row.id===id);sample=draft[id]?{rate:draft[id].rate,pcm:Uint8Array.from(draft[id].pcm)}:decodeWave(reader,row.address);history=[];controls();}
  function remember(){history.push({sample:{rate:sample.rate,pcm:sample.pcm.slice()},edit:draft[id]?structuredClone(draft[id]):null});if(history.length>10)history.shift();}
  function replace(next){const edit={rate:Math.round(next.rate),pcm:Array.from(next.pcm)};validateCryEdits({...project.cryEdits,[hash]:{...draft,[id]:edit}});stop();remember();sample={rate:edit.rate,pcm:Uint8Array.from(edit.pcm)};draft[id]=edit;dirty=true;controls();}
  function list(){const q=$('#crySearch').value.toLowerCase(),rows=native.rows.filter(r=>(r.id+' '+r.name).toLowerCase().includes(q));select.innerHTML=rows.map(r=>`<option value="${r.id}">${esc(r.name)} · ${r.id}</option>`).join('');if(rows.some(r=>r.id===id))select.value=id;else if(rows.length){id=rows[0].id;load();}select.disabled=!rows.length;}
  select.onchange=()=>{id=+select.value;load();};$('#crySearch').oninput=list;
  const guarded=fn=>async()=>{try{$('#cryError').textContent='';await fn();}catch(e){if(canvas.isConnected)$('#cryError').textContent=e.message;else api.error(e);}};
  $('#cryPlay').onclick=guarded(()=>play(sample));$('#cryReversePreview').onclick=guarded(()=>play(draft[id]?sample:decodeWave(reader,native.rows.find(row=>row.id===id).reverseAddress),true));$('#cryStop').onclick=stop;
  $('#cryApply').onclick=guarded(()=>replace(transformSample(sample,{start:+$('#cryStart').value,end:+$('#cryEnd').value,gain:+$('#cryGain').value,semitones:+$('#cryPitch').value,normalize:$('#cryNormalize').checked,reverse:$('#cryReverse').checked})));
  $('#cryUndo').onclick=()=>{const old=history.pop();if(!old)return;stop();sample=old.sample;if(old.edit)draft[id]=old.edit;else delete draft[id];dirty=true;controls();};
  $('#cryReset').onclick=()=>{stop();remember();delete draft[id];sample=decodeWave(reader,native.rows.find(row=>row.id===id).address);dirty=true;controls();};
  $('#cryImport').onclick=()=>$('#cryFile').click();$('#cryFile').onchange=guarded(async()=>{const input=$('#cryFile'),file=input.files[0],expected=id;if(!file)return;input.value='';if(file.size>8e6)throw Error('Use a PCM WAV below 8 MB.');const bytes=new Uint8Array(await file.arrayBuffer());if(!canvas.isConnected||id!==expected||api.project()!==project||api.session()?.reader!==reader)return;replace(readWAV(bytes));});
  $('#cryExport').onclick=guarded(()=>api.save(new Blob([writeWAV(sample)],{type:'audio/wav'}),'Cry_'+native.rows.find(row=>row.id===id).name+'.wav'));list();load();
 }catch(e){api.error(e);}}
 return{open,stop};
}
